    assertClassNames("alpha\u000Bbeta gamma", "alpha\u000Bbeta", "gamma");
    assertClassNames("alpha beta alpha gamma beta", "alpha", "beta", "gamma");
    assertClassNames("alpha\u00A0beta gamma", "alpha\u00A0beta", "gamma");

