package org.jsoup.nodes;

import org.jsoup.Jsoup;
import org.jsoup.select.Elements;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.fail;

/** scratch adversarial harness for cssSelector */
public class CssSelectorFuzzTest {
    static int fails = 0;
    static void check(Document doc, String desc) {
        List<Element> els = doc.select("*");
        for (Element el : els) {
            String q;
            try {
                q = el.cssSelector();
            } catch (Exception e) {
                System.out.println("GEN-EX " + desc + " :: " + describe(el) + " :: " + e);
                fails++;
                continue;
            }
            Elements found;
            try {
                found = doc.select(q);
            } catch (Exception e) {
                System.out.println("SEL-EX " + desc + " :: " + describe(el) + " q=" + q + " :: " + e);
                fails++;
                continue;
            }
            if (found.size() != 1 || found.get(0) != el) {
                System.out.println("MISS " + desc + " :: " + describe(el) + " q=" + q + " hits=" + found.size());
                fails++;
            }
            String q2 = el.cssSelector();
            if (!q.equals(q2)) {
                System.out.println("NONDET " + desc + " :: " + describe(el) + " q=" + q + " q2=" + q2);
                fails++;
            }
        }
    }

    static String describe(Element el) {
        return "<" + el.tagName() + " id='" + el.id() + "' class='" + el.className() + "'>";
    }

    static Document doc(String html) {
        return Jsoup.parse(html);
    }

    @Test void adversarial() {
        // special chars in id
        String[] specials = {"a b", "a.b", "a:b", "a(b)", "a[b]", "a*b", "a\\b", "a'b", "a\"b",
