package org.jsoup.nodes;

import org.jsoup.Jsoup;
import org.jsoup.parser.Parser;
import org.jsoup.select.Elements;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.fail;

/** scratch adversarial harness for cssSelector */
public class CssSelectorFuzz2Test {
    static int fails = 0;

    static String path(Element el) {
        StringBuilder sb = new StringBuilder();
        Node n = el;
        while (n != null) {
            if (n instanceof Element) {
                Element e = (Element) n;
                sb.insert(0, "/" + e.tagName() + "[" + e.siblingIndex() + "]");
            }
            n = n.parentNode;
        }
        return sb.toString();
    }

    static void check(Document doc, String desc) {
        String before = doc.html();
        List<Element> els = doc.select("*");
        for (Element el : els) {
            if (el instanceof Document) continue;
            String q;
            try {
                q = el.cssSelector();
            } catch (Exception e) {
                System.out.println("GEN-EX " + desc + " :: " + path(el) + " :: " + e);
                fails++;
                continue;
            }
            Elements found;
            try {
                found = doc.select(q);
            } catch (Exception e) {
                System.out.println("SEL-EX " + desc + " :: " + path(el) + " q=" + q + " :: " + e);
                fails++;
                continue;
            }
            if (found.size() != 1 || found.get(0) != el) {
                System.out.println("MISS " + desc + " :: " + path(el)
                    + " tag=" + el.tagName() + " id='" + el.id() + "' class='" + el.className() + "'"
                    + " q=" + q + " hits=" + found.size());
                fails++;
            }
            String q2 = el.cssSelector();
            if (!q.equals(q2)) {
                System.out.println("NONDET " + desc + " :: " + path(el) + " q=" + q + " q2=" + q2);
                fails++;
            }
        }
        String after = doc.html();
        if (!before.equals(after)) {
            System.out.println("MUTATED by " + desc);
            fails++;
        }
    }

    @Test void adversarial() {
        // XML parser: case-sensitive tags, namespaces, self-closing
        List<Document> docs = new ArrayList<>();
        docs.add(Jsoup.parse("<root><Item ID='x'/><item id='X'/><fb:comments xmlns:fb='urn:x'>a</fb:comments></root>", "", Parser.xmlParser()));
        docs.add(Jsoup.parse("<r><A/><a/><B b='1'/><b B='2'/></r>", "", Parser.xmlParser()));
        docs.add(Jsoup.parse("<r><c:h/><C:H/><d:i/></r>", "", Parser.xmlParser()));
        docs.add(Jsoup.parse("<html><head></head><body><svg><clipPath/><linearGradient/></svg></body></html>", "", Parser.xmlParser()));
        docs.add(Jsoup.parse("<root id='1'><leaf class='a b c'/></root>", "", Parser.xmlParser()));
        int i = 0;
        for (Document d : docs) check(d, "xml#" + (i++));

        // detached fragments
        Element frag = Jsoup.parseBodyFragment("").body();
        frag.append("<section><h1>T</h1><div class='x'><p>1</p><p>2</p></div></section>");
        check(frag.ownerDocument(), "frag1");

        Element detached = new Element("div").html("<ul><li>a</li><li>b<ol><li>b1</li><li>b2</li></ol></li></ul>");
        // check detached directly via select on the element
        checkDetached(detached, "detached");

        // deeply nested lists/tables with repeated structures
        check(Jsoup.parse("<div><ul><li><ul><li><ul><li>x</li><li>y</li></ul></li></ul></li><li>z</li></ul></div>"), "nested-ul");
        check(Jsoup.parse("<table><thead><tr><th>h1</th><th>h2</th></tr></thead>"
            + "<tbody><tr><td>a</td><td>b</td></tr><tr><td>c</td><td>d</td></tr></tbody></table>"), "table-full");
        check(Jsoup.parse("<picture><source media='x'><source media='y'><img src='z' alt='w'></picture>"), "picture2");

        // root element, body, html
        check(Jsoup.parse("<html><head><title>x</title></head><body><p>hi</p></body></html>"), "full-doc");

        // duplicate id across deeply different structures
        check(Jsoup.parse("<header id=x><div id=x></div></header><section id=x><a id=x></a></section>"), "dupe-ids");

        // same class on every element (Tailwind-like)
        check(Jsoup.parse("<div class='flex p-4'><span class='flex p-4'><em class='flex p-4'>x</em></span></div>"), "all-same-class");

        // whitespace / entity decoded ids and classes
        check(Jsoup.parse("<div id='a&amp;b' class='x&lt;y'></div>"), "entities");
        check(Jsoup.parse("<p class=''>a</p><p>b</p><p class=' '>c</p>"), "empty-classes");

        // selector-special sequences inside identifiers
        String[] nasty = {
            ":root", "#x", ".y", "a,b", "*", "*x", "x*", "::before", ":has(p)",
            "[id]", "a[b='c']", "nth-child(2)", "\\31 ", "a\\.b", "--x", "-",
            "a>b>c", "a b", "a + b", "a~b", "a#b.c[d]", "é:b", "日本.語",
            "\u0000", "\u0001", "\u007F", "\u0080", " ", "ᅟ", "a b",
            "a\rb", "a\fb", "a\tb", "a\vb", "a​b", "﻿x"
        };
        i = 0;
        for (String s : nasty) {
            check(Jsoup.parse("<div id='" + org.jsoup.nodes.Entities.escape(s) + "'></div><div id='"
                + org.jsoup.nodes.Entities.escape(s) + "'></div>"), "nasty-id#" + i);
            check(Jsoup.parse("<p class='" + org.jsoup.nodes.Entities.escape(s) + "'></p><span class='"
                + org.jsoup.nodes.Entities.escape(s) + "'></span>"), "nasty-cls#" + i);
            i++;
        }

        // implicit tags: select>option, dl>dt/dd, table
        check(Jsoup.parse("<select><option>a</option><option>b</option><optgroup label=g><option>c</option></optgroup></select>"), "select");
        check(Jsoup.parse("<dl><dt>t</dt><dd>d</dd><dt>t2</dt><dd>d2</dd></dl>"), "dl");
        check(Jsoup.parse("<table><tr><td><table><tr><td>inner</td></tr></table></td></tr></table>"), "nested-table");

        // round trip tests
        String[] htmls = {
            "<div id='a.b'><span class='x y'></span></div><ul><li>1</li><li>2</li></ul>",
            "<picture><source srcset=a><img class='z[1]'></picture>",
            "<table><tr><td rowspan=2>x</td><td>y</td></tr><tr><td>z</td></tr></table>",
            "<div id='dupe'></div><div id='dupe'></div>",
            "<A CLASS='X'>y</A><a>z</a>"
        };
        i = 0;
        for (String h : htmls) {
            Document d1 = Jsoup.parse(h);
            roundTrip(d1, "rt#" + (i++));
        }

        if (fails > 0) fail(fails + " failures");
    }

    static void checkDetached(Element root, String desc) {
        for (Element el : root.select("*")) {
            String q;
            try {
                q = el.cssSelector();
                Elements found = root.select(q);
                if (found.size() != 1 || found.get(0) != el) {
                    System.out.println("MISS-D " + desc + " :: " + path(el) + " q=" + q + " hits=" + found.size());
                    fails++;
                }
            } catch (Exception e) {
                System.out.println("EX-D " + desc + " :: " + path(el) + " :: " + e);
                fails++;
            }
        }
    }

    static void roundTrip(Document d1, String desc) {
        // map elements by structural path; selector must find the same structural element after reparse
        List<Element> els1 = d1.select("*");
        Document d2 = Jsoup.parse(d1.html());
        List<Element> els2 = d2.select("*");
        if (els1.size() != els2.size()) {
            System.out.println("RT-STRUCT " + desc);
            fails++;
            return;
        }
        for (int j = 0; j < els1.size(); j++) {
            Element e1 = els1.get(j);
            if (e1 instanceof Document) continue;
            String q;
            try { q = e1.cssSelector(); } catch (Exception e) {
                System.out.println("RT-GENEX " + desc + " :: " + path(e1) + " :: " + e);
                fails++; continue;
            }
            Elements found;
            try { found = d2.select(q); } catch (Exception e) {
                System.out.println("RT-SELEX " + desc + " :: " + path(e1) + " q=" + q + " :: " + e);
                fails++; continue;
            }
            if (found.size() != 1 || path(found.get(0)).equals(path(e1)) == false) {
                System.out.println("RT-MISS " + desc + " q=" + q + " hits=" + found.size()
                    + " want=" + path(e1) + (found.size() == 1 ? " got=" + path(found.get(0)) : ""));
                fails++;
            }
        }
    }
}

