package org.jsoup.nodes;

import org.jsoup.Jsoup;
import org.jsoup.internal.StringUtil;
import org.jsoup.select.Elements;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import static org.junit.jupiter.api.Assertions.fail;

/** Randomized fuzzer for cssSelector */
public class CssSelectorFuzz3Test {
    static int fails = 0;

    static final String[] TAGS = {"div", "span", "p", "a", "li", "ul", "ol", "td", "tr", "table",
        "section", "em", "b", "i", "h1", "source", "img", "picture", "dt", "dd", "option", "select", "nav", "header"};

    // characters that may appear in ids/classes
    static final String SPECIAL = " .:\\()[]*#>+~,'\"\\/\t\n\r\f|=^$!?&@%;`{}-_abcABC0129é日本語 ᅟ";

    static String randIdent(Random r) {
        int choice = r.nextInt(10);
        if (choice < 4) {
            // plain-ish
            int len = 1 + r.nextInt(8);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++) {
                if (r.nextInt(3) == 0) sb.append((char) ('a' + r.nextInt(26)));
                else sb.append(SPECIAL.charAt(r.nextInt(SPECIAL.length())));
            }
            return sb.toString();
        } else if (choice == 4) {
            // leading digit
            return (char) ('0' + r.nextInt(10)) + "ab";
        } else if (choice == 5) {
            return "-" + (r.nextBoolean() ? "x" : "1");
        } else if (choice == 6) {
            return String.valueOf((char) (1 + r.nextInt(0x1F))); // control
        } else if (choice == 7) {
            return " ";
        } else if (choice == 8) {
            return "dup";
        } else {
            return "shared";
        }
    }

    static void build(StringBuilder html, Random r, int depth) {
        String tag = TAGS[r.nextInt(TAGS.length)];
        html.append('<').append(tag);
        if (r.nextInt(3) != 0) {
            html.append(" id=\"").append(escAttr(randIdent(r))).append('"');
        }
        if (r.nextInt(2) == 0) {
            int n = 1 + r.nextInt(3);
            html.append(" class=\"");
            for (int c = 0; c < n; c++) {
                if (c > 0) html.append(' ');
                html.append(escAttr(randIdent(r)));
            }
            html.append('"');
        }
        html.append('>');
        if (depth > 0) {
            int kids = r.nextInt(4);
            for (int k = 0; k < kids; k++) build(html, r, depth - 1);
            if (r.nextInt(3) == 0) html.append("text content ");
        } else {
            if (r.nextBoolean()) html.append("x");
        }
        html.append("</").append(tag).append('>');
    }

    static String escAttr(String s) {
        return s.replace("&", "&amp;").replace("\"", "&quot;").replace("<", "&lt;");
    }

    static String path(Element el) {
        StringBuilder sb = StringUtil.borrowBuilder();
        Node n = el;
        while (n instanceof Element) {
            Element e = (Element) n;
            sb.insert(0, "/" + e.tagName() + "[" + e.elementSiblingIndex() + "]");
            n = n.parentNode;
        }
        return StringUtil.releaseBuilder(sb);
    }

    static void checkDoc(Document doc, String desc) {
        String before = doc.html();
        List<Element> els = doc.select("*");
        for (Element el : els) {
            if (el instanceof Document) continue;
            String q, q2;
            try {
                q = el.cssSelector();
                q2 = el.cssSelector();
            } catch (Exception e) {
                System.out.println("GEN-EX " + desc + " :: " + path(el) + " :: " + e);
                fails++;
                continue;
            }
            if (!q.equals(q2)) {
                System.out.println("NONDET " + desc + " q=" + q + " q2=" + q2);
                fails++;
            }
            Elements found;
            try {
                found = doc.select(q);
            } catch (Exception e) {
                System.out.println("SEL-EX " + desc + " :: " + path(el) + " q=" + q + " :: " + e);
                fails++;
                continue;
            }
            if (found.size() != 1 || found.get(0) != el) {
                System.out.println("MISS " + desc + " :: " + path(el)
                    + " tag=" + el.tagName() + " id='" + el.id() + "' class='" + el.className() + "'"
                    + " q=" + q + " hits=" + found.size());
                fails++;
                if (fails > 40) break;
            }
        }
        if (!before.equals(doc.html())) {
            System.out.println("MUTATED by " + desc);
            fails++;
        }
    }

    @Test void randomDom() {
        Random r = new Random(20260928);
        for (int iter = 0; iter < 400 && fails <= 40; iter++) {
            StringBuilder html = new StringBuilder();
            int roots = 1 + r.nextInt(3);
            for (int i = 0; i < roots; i++) build(html, r, r.nextInt(5));
            String h = html.toString();
            Document doc;
            try {
                doc = Jsoup.parse(h);
            } catch (Exception e) {
                continue;
            }
            checkDoc(doc, "iter" + iter);

            // round trip
            Document d2 = Jsoup.parse(doc.html());
            List<Element> e1 = doc.select("*"), e2 = d2.select("*");
            if (e1.size() == e2.size()) {
                for (int j = 0; j < e1.size(); j++) {
                    Element a = e1.get(j), b = e2.get(j);
                    if (a instanceof Document) continue;
                    if (!path(a).equals(path(b))) {
                        System.out.println("RT-STRUCT iter" + iter + " " + path(a) + " vs " + path(b));
                        try {
                            java.nio.file.Files.write(java.nio.file.Paths.get("/tmp/fuzz-iter" + iter + ".html"),
                                h.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                        } catch (Exception ignore) {}
                        fails++;
                        break;
                    }
                    String q = a.cssSelector();
                    Elements found;
                    try {
                        found = d2.select(q);
                    } catch (Exception ex) {
                        System.out.println("RT-SELEX iter" + iter + " q=" + q + " :: " + ex);
                        fails++;
                        continue;
                    }
                    if (found.size() != 1 || !path(found.get(0)).equals(path(a))) {
                        System.out.println("RT-MISS iter" + iter + " q=" + q + " hits=" + found.size()
                            + " want=" + path(a) + (found.size() == 1 ? " got=" + path(found.get(0)) : ""));
                        fails++;
                    }
                }
            }
        }
        if (fails > 0) fail(fails + " failures");
    }
}

