            for (int i = 0; i < roots; i++) build(html, r, r.nextInt(5));
            String h = html.toString();
            Document doc;
            try {
                doc = Jsoup.parse(h);
            } catch (Exception e) {
                continue;
            }
            checkDoc(doc, "iter" + iter);

            // round trip
            Document d2 = Jsoup.parse(doc.html());
            List<Element> e1 = doc.select("*"), e2 = d2.select("*");
            if (e1.size() == e2.size()) {
                for (int j = 0; j < e1.size(); j++) {
                    Element a = e1.get(j), b = e2.get(j);
                    if (a instanceof Document) continue;
                    if (!path(a).equals(path(b))) {
                        System.out.println("RT-STRUCT iter" + iter + " " + path(a) + " vs " + path(b));
                        try {
                            java.nio.file.Files.write(java.nio.file.Paths.get("/tmp/fuzz-iter" + iter + ".html"),
                                h.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                        } catch (Exception ignore) {}
                        fails++;
                        break;
                    }
                    String q = a.cssSelector();
                    Elements found;
                    try {
                        found = d2.select(q);
                    } catch (Exception ex) {
                        System.out.println("RT-SELEX iter" + iter + " q=" + q + " :: " + ex);
